urlset:
{{ site.url }}{% if quizzes %}{{ quizzes[0].date.isoformat() }}{% endif %}
{% for q in quizzes %}

  {{ site.url }}quiz/{{ q.slug }}/
  {{ q.date.isoformat() }}
  {{ absolute(q.thumb_url) }}

{% endfor %}
{{ site.url }}tags/
{% for t in tags %}
{{ site.url }}tags/{{ t|slugify }}/
{% endfor %}
{{ site.url }}about/
{{ site.url }}blog/{% if posts %}{{ posts[0].date.isoformat() }}{% endif %}
{% for p in posts %}

  {{ site.url }}blog/{{ p.slug }}/
  {{ p.date.isoformat() }}
  {% if p.cover %}{{ absolute(p.cover) }}{% endif %}

{% endfor %}
